def solve_n_queens(n, fixed):
    def can_place(pos, ocol, orow):
        for r, c in enumerate(pos):
            if c == ocol or abs(c - ocol) == abs(r - orow):
                return False
        return True

    def solve(row, pos):
        if row == n:
            return pos
        if row in fixed:
            if can_place(pos, fixed[row], row):
                return solve(row + 1, pos + [fixed[row]])
            else:
                return None
        for col in range(n):
            if can_place(pos, col, row):
                res = solve(row + 1, pos + [col])
                if res:
                    return res
        return None

    return solve(0, [])

print(solve_n_queens(14, {4: 4, 6: 1}))
